func repoWorktreeRoot(repo *git.Repository) (string, error) {
	worktree, err := repo.Worktree()
	if err != nil {
		return "", err
	}
	root := worktree.Filesystem().Root()
	if root == "" {
		return "", errors.New("repository worktree filesystem has no root path")
	}
	return root, nil
}

func gitNoLazyFetchCommand(ctx context.Context, repoRoot string, args ...string) *exec.Cmd {
	if repoRoot != "" {
		args = append([]string{"-C", repoRoot}, args...)
	}
	cmd := exec.CommandContext(ctx, "git", args...)
	cmd.Env = append(os.Environ(), "GIT_NO_LAZY_FETCH=1")
	return cmd
}

